import{_ as a,o,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"صرف علم کی واپسی کا اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/87-仅回传知识原则.md","filePath":"ur/87-仅回传知识原则.md","lastUpdated":null}'),d={name:"ur/87-仅回传知识原则.md"};function l(u,t,i,h,q,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="صرف-علم-کی-واپسی-کا-اصول" tabindex="-1">صرف علم کی واپسی کا اصول <a class="header-anchor" href="#صرف-علم-کی-واپسی-کا-اصول" aria-label="Permalink to &quot;صرف علم کی واپسی کا اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>87</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>صرف علم کی واپسی، معلومات کی پاکیزگی، مادے کی واپسی پر پابندی، علم کی انکوڈنگ، واپسی کی آڈیٹ</td></tr></tbody></table><h2 id="_1-اصول-کی-قانونی-پس-منظر-اور-بنیادی-خیال" tabindex="-1">1. اصول کی قانونی پس منظر اور بنیادی خیال <a class="header-anchor" href="#_1-اصول-کی-قانونی-پس-منظر-اور-بنیادی-خیال" aria-label="Permalink to &quot;1. اصول کی قانونی پس منظر اور بنیادی خیال&quot;">​</a></h2><p>&quot;صرف علم کی واپسی&quot; کا اصول اینکر سمبیوسس تہذیب کی بین السطح اور وقت کے پیچھے ہٹنے والی آثار قدیمہ کے بنیادی اصولوں میں سے ایک ہے، اس کی قانونی ابتدا &quot;سمبیوسس آئین&quot; کے آٹھواں چالیسواں آرٹیکل میں واپس جا سکتی ہے: &quot;کسی دوسری سطح یا کسی دوسرے وقت کی مدت سے حاصل کردہ کوئی بھی مادہ، توانائی اور جاندار چیز، خاص اجازت کے بغیر اپنی سطح پر نہیں لائی جا سکتی؛ آثار قدیمہ کی سرگرمیوں کا جائز نتیجہ صرف تجریدی علم اور معلومات تک محدود ہے۔&quot; اس اصول کا قیام، ہینگ یوان ژو کی ابتدائی بین السطح دریافت کے دردناک سبق کو خلاصہ کرنے کے بعد کیا گیا ایک ادارہ جاتی انتخاب ہے۔</p><p>اینکر سمبیوسس تہذیب کے قیام کے ابتدائی دور میں، بین السطح دریافت ابھی بے ترتیب حالت میں تھی۔ کچھ دریافت کاروں نے دوسری سطحوں سے مادے کے نمونے، توانائی کے کرسٹل اور یہاں تک کہ جاندار چیزیں بھی اپنی سطح پر لے آئیں تحقیق کے لیے، جس کے نتیجے میں متعدد سنگین &quot;بین السطح آلودگی کے واقعات&quot; رونما ہوئے۔ سب سے مشہور کیس &quot;غیر ملکی کرسٹل واقعہ&quot; ہے — توانائی کے اظہار کی سطح سے لایا گیا ایک توانائی کا کرسٹل، اس کے قانونی پیرامیٹرز اپنی سطح سے مطابقت نہ رکھنے کی وجہ سے، اپنی سطح کے قانونی نیٹ ورک میں تین سال تک جاری رہنے والی قانونی خرابی پیدا کی، جس کے نتیجے میں تین ستاروں کے علاقوں کے سادھک نظام میں غیر معمولیات پیدا ہوئیں، لاکھوں سادھکوں کو مختلف درجے کے نقصان اٹھانا پڑا۔ بعد کی تحقیقات سے پتہ چلتا ہے کہ اگر اس وقت &quot;صرف علم کی واپسی&quot; کے اصول پر عمل کیا جاتا تو یہ تباہی مکمل طور پر بچائی جا سکتی تھی۔</p><p>&quot;صرف علم کی واپسی&quot; کے اصول کا بنیادی خیال یہ ہے: علم بین السطح تہذیبوں کے تبادلے میں واحد محفوظ ذریعہ ہے۔ مادہ اور توانائی اپنی ماخذ سطح کی قانونی معلومات لے کر چلتے ہیں، اور مختلف قانونی ماحول میں داخل ہونے کے بعد غیر متوقع ردعمل پیدا کر سکتے ہیں؛ جبکہ علم بطور تجریدی معلومات، مناسب انکوڈنگ اور پاکیزگی کے بعد، اپنی ماخذ سطح کے قانونی نشانات کو الگ کر کے، بین السطح اشتراک کے قابل محفوظ وسیلہ بن سکتا ہے۔</p><h2 id="_2-علم-کی-تعریف-اور-درجہ-بندی" tabindex="-1">2. &quot;علم&quot; کی تعریف اور درجہ بندی <a class="header-anchor" href="#_2-علم-کی-تعریف-اور-درجہ-بندی" aria-label="Permalink to &quot;2. &quot;علم&quot; کی تعریف اور درجہ بندی&quot;">​</a></h2><p>&quot;صرف علم کی واپسی&quot; کے اصول کے قانونی فریم ورک کے تحت، &quot;علم&quot; کی سخت تعریف اور درجہ بندی ہے۔ ہر معلومات کو &quot;علم&quot; سمجھ کر آزادانہ طور پر واپس نہیں کیا جا سکتا — صرف وہی تجریدی معلومات جو &quot;معلومات کی پاکیزگی&quot; کے عمل سے گزر چکی ہیں اور اس بات کی تصدیق ہو چکی ہے کہ وہ کسی بھی قانونی آلودگی کو نہیں لے کر چلتی، وہی واپسی کے معیار پر پوری اترتی ہیں۔</p><p>علم کو اس کی تجریدیت کی سطح اور حفاظتی سطح کے مطابق تین قسموں میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>علم کی قسم</th><th>تعریف</th><th>حفاظتی سطح</th><th>واپسی کی ضرورت</th></tr></thead><tbody><tr><td>پہلی قسم کا علم (خالص تجریدی علم)</td><td>مادے کے وہیکل سے مکمل طور پر الگ تجریدی تصورات، ریاضی کے نظریات، منطقی تخمینہ، فلسفیانہ خیالات وغیرہ</td><td>سب سے زیادہ (سبز)</td><td>براہ راست واپس کیا جا سکتا ہے، خاص منظوری کی ضرورت نہیں</td></tr><tr><td>دوسری قسم کا علم (وضاحتی علم)</td><td>معروضی چیزوں کے بارے میں وضاحتی معلومات، بشمول تاریخی ریکارڈ، جغرافیائی ڈیٹا، حیاتیاتی خصوصیات، ثقافتی وضاحت وغیرہ</td><td>درمیانی (پیلا)</td><td>معلومات کی پاکیزگی کے عمل سے گزرنا ضروری ہے، سطح انتظامیہ بیورو کی منظوری کے بعد واپس کیا جائے گا</td></tr><tr><td>تیسری قسم کا علم (تکنیکی علم)</td><td>مخصوص تکنیکی پیرامیٹرز، انجینئرنگ اسکیم، سادھک کے طریقے پر مشتمل عملی علم</td><td>کم (نارنجی)</td><td>سخت معلومات کی پاکیزگی اور حفاظتی تشخیص سے گزرنا ضروری ہے، اینکر کونسل کی خاص منظوری کے بعد واپس کیا جائے گا</td></tr></tbody></table><p>درج ذیل مواد &quot;علم&quot; کے زمرے میں نہیں آتے، اور ان کی واپسی سختی سے ممنوع ہے: کسی بھی شکل کے مادے کے نمونے (جرثوموں، خلیوں، جین کے ٹکڑوں سمیت)، کسی بھی شکل کے توانائی کے کرسٹل یا توانائی کے ذخیرہ کرنے والے آلات، کوئی بھی خود مختار شعور رکھنے والا جاندار چیز یا شعور کی چیز، کوئی بھی ایسا اصل ڈیٹا جو معلومات کی پاکیزگی سے نہ گزرا ہو، اور کوئی بھی ایسی تکنیکی تفصیل جو لوٹ مار کے سادھک میں استعمال ہو سکتی ہے۔</p><h2 id="_3-معلومات-کی-پاکیزگی-کی-ٹیکنالوجی" tabindex="-1">3. معلومات کی پاکیزگی کی ٹیکنالوجی <a class="header-anchor" href="#_3-معلومات-کی-پاکیزگی-کی-ٹیکنالوجی" aria-label="Permalink to &quot;3. معلومات کی پاکیزگی کی ٹیکنالوجی&quot;">​</a></h2><p>معلومات کی پاکیزگی واپس کیے جانے والے علم کی حفاظت کو یقینی بنانے کا بنیادی تکنیکی حصہ ہے۔ اس کا بنیادی مقصد یہ ہے کہ اصل معلومات میں موجود ماخذ سطح کے قانونی نشانات کو مکمل طور پر الگ کیا جائے، صرف خالص معنوی مواد کو ہی برقرار رکھا جائے۔ معلومات کی پاکیزگی کا عمل چار مراحل میں تقسیم ہے:</p><h3 id="_3-1-معلومات-کی-تخریب" tabindex="-1">3.1 معلومات کی تخریب <a class="header-anchor" href="#_3-1-معلومات-کی-تخریب" aria-label="Permalink to &quot;3.1 معلومات کی تخریب&quot;">​</a></h3><p>سب سے پہلے واپس کیے جانے والی اصل معلومات کو ساختی طور پر تخریب کیا جاتا ہے، اور اسے &quot;معنوی مواد&quot; اور &quot;وہیکل کے نشانات&quot; کے دو حصوں میں تقسیم کیا جاتا ہے۔ معنوی مواد وہ تجریدی معنی ہے جو معلومات بیان کرنا چاہتی ہے، وہیکل کے نشانات وہ ماخذ سطح کے قانونی پیرامیٹرز ہیں جو معلومات ذخیرہ کرنے اور منتقل کرنے کے عمل میں جذب کر لیتی ہے۔ معلومات کی تخریب &quot;معنی-وہیکل علیحدگی الگورتھم&quot; کے ذریعے ہوتی ہے، یہ الگورتھم معلومات میں موجود معنوی اجزاء اور قانونی اجزاء کو شناخت اور الگ کرنے کی صلاحیت رکھتا ہے۔</p><h3 id="_3-2-قانونی-علیحدگی" tabindex="-1">3.2 قانونی علیحدگی <a class="header-anchor" href="#_3-2-قانونی-علیحدگی" aria-label="Permalink to &quot;3.2 قانونی علیحدگی&quot;">​</a></h3><p>الگ کیے گئے وہیکل کے نشانات پر مکمل قانونی علیحدگی کی جاتی ہے۔ علیحدگی کا طریقہ یہ ہے کہ معلومات کو &quot;قانونی غیر جانبداری چینل&quot; سے گزرایا جاتا ہے — یہ ایک خاص ٹرانسمیشن چینل ہے جس کے قانونی پیرامیٹرز مکمل طور پر غیر جانبدار مقرر کیے گئے ہیں، جب معلومات اس سے گزرتی ہے تو اس کے ساتھ لے جانے والے تمام غیر جانبدار قانونی پیرامیٹرز چینل کی دیوار کے ذریعے جذب کر لیے جاتے ہیں۔ قانونی علیحدگی کے بعد، معلومات میں اب کوئی بھی ماخذ سطح کا قانونی نشان نہیں رہتا۔</p><h3 id="_3-3-معنوی-تعمیر-نو" tabindex="-1">3.3 معنوی تعمیر نو <a class="header-anchor" href="#_3-3-معنوی-تعمیر-نو" aria-label="Permalink to &quot;3.3 معنوی تعمیر نو&quot;">​</a></h3><p>قانونی علیحدگی کی بنیاد پر، معنوی مواد کی دوبارہ انکوڈنگ کی جاتی ہے، اور اپنی سطح کے معیاری معلومات انکوڈنگ سسٹم کا استعمال کرتے ہوئے معلومات کو دوبارہ بنایا جاتا ہے۔ معنوی تعمیر نو اس بات کو یقینی بناتی ہے کہ واپس کیا گیا علم اپنی سطح کے قانونی ماحول میں صحیح طریقے سے پڑھا اور سمجھا جا سکے، ساتھ ہی یہ ممکنہ ماخذ سطح کے معلومات کے ڈھانچے کو مزید ختم کر دیتی ہے۔</p><h3 id="_3-4-حفاظتی-جانچ" tabindex="-1">3.4 حفاظتی جانچ <a class="header-anchor" href="#_3-4-حفاظتی-جانچ" aria-label="Permalink to &quot;3.4 حفاظتی جانچ&quot;">​</a></h3><p>پاک کردہ معلومات کو سخت حفاظتی جانچ سے گزرنا ضروری ہے، جس میں شامل ہیں: قانونی بقایا جانچ (اس بات کی تصدیق کہ معلومات کوئی بھی غیر ملکی قانونی پیرامیٹر نہیں لے کر چل رہی)، معنوی مکملیت کی جانچ (اس بات کی تصدیق کہ پاکیزگی کے عمل نے معلومات کے معنوی مواد کو تبدیل نہیں کیا)، اور ممکنہ خطرے کی تشخیص (اپنی سطح میں اس علم کے پھیلاؤ سے ہونے والے سماجی اور حفاظتی اثرات کا اندازہ لگانا)۔ صرف وہی معلومات جو تینوں جانچوں میں کامیاب ہو جائیں، انہیں واپس کرنے کی اجازت دی جاتی ہے۔</p><h2 id="_4-واپسی-کا-عمل-اور-آڈیٹ-کا-نظام" tabindex="-1">4. واپسی کا عمل اور آڈیٹ کا نظام <a class="header-anchor" href="#_4-واپسی-کا-عمل-اور-آڈیٹ-کا-نظام" aria-label="Permalink to &quot;4. واپسی کا عمل اور آڈیٹ کا نظام&quot;">​</a></h2><p>علم کی واپسی سخت عمل کی انتظامیہ پر عمل کرتی ہے۔ ایک مکمل واپسی آپریشن میں درج ذیل مراحل شامل ہیں:</p><ol><li><strong>علم کی تنظیم</strong>: آثار قدیمہ کی ٹیم تحقیق کے نتائج کو معیاری علم دستاویزات میں ترتیب دیتی ہے، علم کی قسم اور مواد کے خلاصے کو واضح طور پر نشان زد کرتی ہے۔</li><li><strong>پاکیزگی کی درخواست</strong>: سطح انتظامیہ بیورو یا وقت قانون کمیٹی کو علم کی پاکیزگی اور واپسی کی درخواست جمع کرواتی ہے، ساتھ میں علم دستاویز اور آثار قدیمہ کے کام کی اجازت فائل منسلک کرتی ہے۔</li><li><strong>معلومات کی پاکیزگی</strong>: پیشہ ور معلومات کی پاکیزگی ٹیکنالوجی ٹیم علم دستاویز پر چار مراحل کی معلومات کی پاکیزگی کا عمل انجام دیتی ہے۔</li><li><strong>حفاظتی جانچ</strong>: پاک کردہ علم کو خودمختار حفاظتی جانچ ادارے کے ذریعے تین جانچوں سے گزرایا جاتا ہے۔</li><li><strong>منظوری واپسی</strong>: جانچ میں کامیاب ہونے کے بعد، منظوری ادارہ واپسی کی اجازت پر دستخط کرتا ہے، علم اینکر نیٹ ورک کے انکرپٹڈ چینل کے ذریعے اپنی سطح کے علمی ڈیٹا بیس میں واپس بھیج دیا جاتا ہے۔</li><li><strong>ذخیرے میں اندراج</strong>: واپس کیا گیا علم اپنی سطح کے علمی ذخیرے کی تصدیق کے بعد باضابطہ طور پر ذخیرے میں اندراج ہو جاتا ہے، اور مناسب اجازت رکھنے والے محققین کے لیے کھول دیا جاتا ہے۔</li></ol><p>تمام واپسی آپریشنز کو &quot;واپسی کی آڈیٹ&quot; سے گزرنا ضروری ہے۔ آڈیٹ کے مواد میں شامل ہیں: واپس کئے گئے علم کا ماخذ جائز ہے یا نہیں، پاکیزگی کا عمل قواعد کے مطابق ہے یا نہیں، حفاظتی جانچ مکمل ہے یا نہیں، منظوری کا طریقہ کار قانونی ہے یا نہیں۔ آڈیٹ اینکر نگرانی کمیٹی کے تحت علم واپسی آڈیٹ دفتر کی ذمہ داری ہے، جو ہر سہ ماہی میں اس سہ ماہی کے تمام واپسی آپریشنز کی نمونہ جانچ کرتا ہے، اور ہر سال ایک مکمل آڈیٹ کرتا ہے۔ آڈیٹ کے نتائج اینکر کونسل کو رپورٹ کیے جاتے ہیں، اور خلاصہ عوام کے سامنے شائع کیا جاتا ہے۔</p><h2 id="_5-قانون-کی-خلاف-ورزی-اور-قانونی-ذمہ-داری" tabindex="-1">5. قانون کی خلاف ورزی اور قانونی ذمہ داری <a class="header-anchor" href="#_5-قانون-کی-خلاف-ورزی-اور-قانونی-ذمہ-داری" aria-label="Permalink to &quot;5. قانون کی خلاف ورزی اور قانونی ذمہ داری&quot;">​</a></h2><p>&quot;صرف علم کی واپسی&quot; کے اصول کی خلاف ورزی کرنے والے طرز عمل میں شامل ہیں: بغیر منظوری کے غیر پاک کردہ معلومات واپس کرنا، مادے کے نمونے کو علم کے چھڑے میں واپس کرنا، واپس کیے گئے علم میں جان بوجھ کر ماخذ سطح کے قانونی نشانات چھپانا، اور دوسروں کی غیر قانونی واپسی میں مدد کرنا۔</p><p>&quot;سمبیوسس آئین&quot; اور &quot;بین السطح تعامل انتظامیہ قانون&quot; کے مطابق، قانون کی خلاف ورزی والی واپسی کے طرز عمل کی قانونی ذمہ داری میں شامل ہیں: قانون کی خلاف ورزی والی واپس کی گئی چیزوں اور معلومات کو ضبط کرنا، متعلقہ فرد کی آثار قدیمہ اور گزر کی قابلیت کو معطل یا منسوخ کرنا، قانون کی خلاف ورزی والی چیزوں کی قیمت سے 10 گنا یا اس سے زیادہ جرمانہ عائد کرنا، سنگین صورتوں میں قید کی سزا، اور قانونی آلودگی یا ماحولیاتی نقصان کی صورت میں تمام مرمت کے اخراجات اور معاوضے کی ذمہ داری اٹھانا۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>&quot;صرف علم کی واپسی&quot; کا اصول اینکر سمبیوسس تہذیب کی بین السطح تعامل کے شعبے میں حکمت کی نچلی حد ہے۔ یہ سخت تعریف، بالغ پاکیزگی کی ٹیکنالوجی، قواعد کے مطابق واپسی کے عمل اور سخت قانونی ذمہ داری کے ذریعے، ایک مضبوط &quot;علمی حفاظتی فائر وال&quot; بناتا ہے۔ اس اصول کی معنویت نہ صرف جسمانی سطح کی آلودگی کو روکنا ہے، بلکہ اس سے بھی زیادہ اہم بات یہ ہے کہ اس نے تہذیبوں کے تبادلے کا ایک اخلاقی نقطہ نظر قائم کیا ہے — تہذیبوں کے درمیان تعامل کا مرکز خیالات کے تصادم ہونا چاہیے، نہ کہ مادے کی لوٹ مار کا مقصد۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>84-آثار قدیمہ پروٹوکول کا عمومی خاکہ</li><li>88-بین السطح اخلاقی رہنما اصول</li><li>66-بین السطح مواصلاتی ٹیکنالوجی</li></ul>',32)])])}const p=a(d,[["render",l]]);export{_ as __pageData,p as default};
